def solve(payload):
    # Extract parameters from payload
    hex_str = payload.get('hex')
    width = payload.get('width')
    byte_order = payload.get('byte_order')
    signed = payload.get('signed')
    sentinel_codes = payload.get('sentinel_codes', [])
    scale = payload.get('scale')
    rounding_places = payload.get('rounding_places', 0)

    # Validating parameters
    if width not in {8, 16, 24, 32}:
        return {'valid': False, 'disposition': 'invalid_width'}
    if byte_order not in {'big', 'little'}:
        return {'valid': False, 'disposition': 'invalid_byte_order'}
    if not isinstance(signed, bool):
        return {'valid': False, 'disposition': 'invalid_signed'}
    if not isinstance(scale, (int, float)) or scale <= 0:
        return {'valid': False, 'disposition': 'invalid_scale'}
    if not (0 <= rounding_places <= 12):
        return {'valid': False, 'disposition': 'invalid_rounding_places'}
    if not isinstance(sentinel_codes, list):
        return {'valid': False, 'disposition': 'invalid_sentinel_codes'}

    # Process hex string
    processed_hex = hex_str.replace(' ', '').replace('_', '')
    bytes_needed = width // 8
    if len(processed_hex) != bytes_needed * 2:
        return {'valid': False, 'disposition': 'invalid_hex_length'}

    try:
        hex_bytes = bytes.fromhex(processed_hex)
    except ValueError:
        return {'valid': False, 'disposition': 'invalid_hex'}

    # Check if any sentinel code matches the raw_count
    raw_count = int.from_bytes(hex_bytes, byteorder=byte_order)
    for code in sentinel_codes:
        if not isinstance(code, int) or code < 0 or code > (1 << width) - 1:
            return {'valid': False, 'disposition': 'invalid_sentinel_code'}
        if code == raw_count:
            return {'valid': False, 'disposition': 'sentinel_match'}

    # Compute signed count
    width_bits = width
    if signed:
        if raw_count >= (1 << (width_bits - 1)):
            count = raw_count - (1 << width_bits)
        else:
            count = raw_count
    else:
        count = raw_count

    # Compute value and round
    try:
        value = count * scale
    except:
        return {'valid': False, 'disposition': 'invalid_scale'}

    try:
        rounded_value = round(value, rounding_places)
    except:
        return {'valid': False, 'disposition': 'invalid_rounding_places'}

    return {'valid': True, 'value': rounded_value}
```

### Explanation:
- **Parameter Extraction**: Extracts all required parameters from the payload.
- **Validation**: Ensures all inputs are within acceptable ranges and types.
- **Hex Processing**: Normalizes and validates the hex string length, converting it to bytes.
- **Sentinel Check**: Compares the raw count (unsigned) with sentinel codes. Any match results in a sentinel error.
- **Signed Conversion**: If enabled, adjusts the raw count to two's complement format.
- **Scaling and Rounding**: Multiplies by the scale factor and rounds to the specified decimal places.
- **Output**: Returns a dictionary with whether the result is valid and the final value. Errors are returned in specific formats for validation.

